/bin/bash -lc "python3 - <<'PY'
# Load local files already downloaded [REDACTED LOCAL PATH] [REDACTED LOCAL PATH]
A={}; B={}
for label,path in [('A','[REDACTED LOCAL PATH]'),('B','[REDACTED LOCAL PATH]')]:
 for l in open(path).read().splitlines()[1:]:
  p=l.split('\\t')
  if len(p)>=5:
   d=A if label=='A' else B
   d[p[0]]=(float(p[3]),float(p[4]))
common=set(A)&set(B)
for minmax in [50,100,200,500,1000,3000]:
 print('\\nminmax',minmax)
 res=[]
 for x in common:
  if x.startswith('ENST'): continue
  a_t,a_n=A[x]; b_t,b_n=B[x]
  m=max(a_n,b_n); diff=abs(a_n-b_n)
  if m>=minmax:
   res.append((diff,m,a_n,b_n,x,a_t,b_t))
 res.sort(reverse=True)
 for r in res[:20]: print(r)
PY"

